<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title class="text-white" v-if="is_edit"
          >{{ $t('edit_group')
          }}<span class="text-weight-bold"></span>
        </q-toolbar-title>
        <q-toolbar-title class="text-white" v-else
          >{{ $t('create_group') }}<span class="text-weight-bold"></span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (!new_model['validate'] || new_model['required_error']
                  ? 'column-error-border error-validation'
                  : '')
              "
              v-model="new_model['name']"
              :placeholder="$t('group_name')"
              :hint="message"
              counter
              maxlength="80"
            >
              <template v-slot:append>
                <q-icon
                  v-if="!new_model['validate'] || new_model['required_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="!new_model['validate']">
                      {{ message }}
                    </template>
                    <template v-if="new_model['required_error']">
                      {{ $t('field_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-input
              v-model="new_model['description']"
              outlined
              type="textarea"
              autogrow
              :placeholder="$t('description')"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn :label="$t('cancel')" v-close-popup appearance="cancel" />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import { useDocPermissionsStore } from 'src/store/main';
import { onlyNumbersAndCharacters } from 'src/utils/general';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    is_edit: {
      type: Boolean,
      default: false,
    },
    name: {
      type: String || null,
      default: null,
    },
    id: {
      type: String || null,
      default: null,
    },
  },
  components: {},
  data() {
    return {
      message: this.$t('NO_SPACES_SPECIAL_CHARS'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    const permission_store = useDocPermissionsStore();
    const { createGroup, editGroup } = permission_store;
    const { getPermissionsByGroupId } = storeToRefs(permission_store);

    return {
      getPermissionsByGroupId,
      createGroup,
      editGroup,
      new_model: ref(model),
      loading: ref(false),
      group_data: ref([] as any),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
    if (this.is_edit) {
      this.group_data = JSON.parse(
        JSON.stringify(this.getPermissionsByGroupId(this.id)),
      );
      this.new_model['name'] = this.name;
      this.new_model['description'] = this.group_data.description;
    }
  },
  methods: {
    setNewModel() {
      this.new_model['name'] = '';
      this.new_model['description'] = '';
      this.new_model['validate'] = true;
      this.new_model['required_error'] = false;
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        if (this.is_edit) {
          await this.editExistingRow();
        } else {
          await this.saveNewRow();
        }

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async editExistingRow() {
      const data = {
        name: this.new_model['name'],
        org_id: getOrgId(),
        only_assigned_documents: this.group_data.only_assigned_documents,
        description: this.new_model['description'],
      };
      await this.editGroup(this.id, data);
      this.setNewModel();
      const event = new CustomEvent('group_edited', {});
      document.dispatchEvent(event);
      notify.success(this.$t('GROUP_UPDATED'));
    },
    async saveNewRow() {
      const data = {
        name: this.new_model['name'],
        description: this.new_model['description'],
      };

      await this.createGroup(data);
      this.setNewModel();
      const event = new CustomEvent('group_added', {});
      document.dispatchEvent(event);
      notify.success(this.$t('group_created'));
    },

    validateRow(row: any) {
      let validate = true;

      if (!row['name'] || row['name'].length == 0) {
        row.required_error = true;
        return false;
      }

      if (!onlyNumbersAndCharacters(row['name'])) {
        row.validate = false;
        return false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
