<template>
  <!-- Toolbar: Search + Add User -->
  <div class="row q-pb-sm">
    <q-input
      outlined
      debounce="300"
      color="primary"
      dense
      v-model="filter"
      class="search-input"
    >
      <template v-slot:append>
        <q-icon name="search" />
      </template>
    </q-input>
    <q-space />
    <f-btn :label="$t('add_user')" class="q-ml-sm float-right" @click="openUserDlg()" />
  </div>


  <div class="full-width members-table-fill">
    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="manage_user_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      flat-style
      table-height="100%"
      @row-action="handleRowAction"
    />
  </div>


  <q-dialog
    v-model="add_users_dialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="add_users_dialog = false"
  >
    <q-card style="width: 700px; max-width: 1060px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('add_user') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <q-card-section class="row items-center q-pb-none"> </q-card-section>

      <q-card-section>
        <div class="table-container col-sm-12 col-md-12 col-lg-12">
          <q-select
            outlined
            v-model="selectedUserId"
            :options="usersDropdownList"
            use-input
            emit-value
            map-options
            @filter="filterUserByName"
            :label="$t('select_user')"
          >
            <template v-slot:no-option>
              <q-item>
                <q-item-section>
                  {{ $t('no_data_found') }}
                </q-item-section>
              </q-item>
            </template>
          </q-select>
        </div>
      </q-card-section>

      <q-card-section>
        <div class="table-container col-sm-12 col-md-12 col-lg-12">
          <q-select
            outlined
            v-model="removeFromOtherGroups"
            :options="[
              { value: false, label: $t('no') },
              { value: true, label: $t('yes') },
            ]"
            emit-value
            map-options
            :label="$t('remove_from_other_groups')"
          />
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" v-close-popup />

        <q-btn
          @click="assigneeGroupToUser()"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <Loader />
</template>

<script lang="ts">
import { Acl } from 'src/core/acls/index';
import Loader from 'src/components/Loader.vue';
import { ApiExceptions } from 'src/exceptions';
import { useDropdownStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { defineComponent, ref, shallowRef } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { documentPermissionsApiService } from 'src/services';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  mixins: [helperMixin],
  components: { Loader, DocBitsTable },
  props: {
    groupId: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      current_user_id: '',
    };
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const needle = this.filter.toLowerCase();
      return this.rows.filter((row: any) =>
        (row.user_name || '').toLowerCase().includes(needle),
      );
    },
  },
  mounted: function () {
    this.current_user_id = getUserDetailFromkey('id');
    this.prepareTableData();
    this.dropdownStore.prepareUsersDropdown();
    this.dropdownStore.prepareBooleanList();
  },
  methods: {
    async prepareTableData() {
      await this.getGroupUsers();
      this.prepareTableColumns();
      this.prepareTableRows();
    },
    async getGroupUsers() {
      let response = null;
      this.showLoading();
      try {
        response = await documentPermissionsApiService.getGroupUsers(
          this.groupId,
        );
        if (!response) {
          throw response;
        }
        this.groupUsers = response;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    prepareTableColumns() {
      this.columns = [
        {
          name: 'user_name',
          label: this.$t('name'),
          field: 'user_name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },
    prepareTableRows() {
      this.rows = [];
      for (let user of this.groupUsers) {
        user['user_name'] = user.first_name + ' ' + user.last_name;
      }
      this.rows = this.groupUsers;
    },
    async unassignUser(user_id: number) {
      this.showLoading();
      try {
        await documentPermissionsApiService.removeUserFromGroup(
          this.groupId,
          user_id.toString(),
        );
        this.removeUser(user_id);
        await this.updateUserPermissions(user_id);
        notify.success(this.$t('message_success_with_await'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    removeUser(user_id: number) {
      const data_index = this.rows.findIndex((row: any) => row.id === user_id);
      if (data_index === -1) {
        return;
      }
      this.rows.splice(data_index, 1);
    },
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.unassignUser(row.id);
      }
    },
    async assigneeGroupToUser() {
      if (!this.selectedUserId) {
        notify.error(this.$t('select_user'));
        return;
      }

      this.showLoading();
      try {
        await documentPermissionsApiService.addUserToGroup(
          this.groupId,
          this.selectedUserId.toString(),
          this.removeFromOtherGroups,
        );
        this.add_users_dialog = false;
        this.addNewUser();
        await this.updateUserPermissions(this.selectedUserId);
        notify.success(this.$t('message_success_with_await'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    addNewUser() {
      const newUser = JSON.parse(
        JSON.stringify(this.dropdownStore.usersMap.get(this.selectedUserId)),
      );
      newUser['user_name'] = newUser.first_name + ' ' + newUser.last_name;
      this.rows.push(newUser);
    },
    openUserDlg() {
      this.add_users_dialog = true;
      this.selectedUserId = null;
      this.prepareDropdownData();
    },
    prepareDropdownData() {
      this.usersList = [];
      let usersMap = new Map(
        JSON.parse(JSON.stringify(Array.from(this.dropdownStore.usersMap))),
      );

      for (const user of this.rows) {
        usersMap.delete(user.id);
      }

      usersMap.forEach((userObj: any, key: any) => {
        this.usersList.push({
          value: key,
          label: userObj.first_name + ' ' + userObj.last_name,
        });
      });

      this.usersDropdownList = this.usersList;
    },

    async updateUserPermissions(user_id: number) {
      if (this.current_user_id !== String(user_id)) {
        return;
      }
      await Acl.fetch();
    },
    filterUserByName(val: any, update: any) {
      if (val === '') {
        update(() => {
          this.usersDropdownList = this.usersList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.usersDropdownList = this.usersList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
  },
  setup() {
    const filter = ref('');
    const columns = ref([] as UnifiedTableColumn[]);

    const dropdownStore = useDropdownStore();
    let usersList = ref([] as any);

    const rowActions: RowActionItem[] = [
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
    ];

    return {
      filter,
      columns,
      usersList,
      dropdownStore,
      rowActions,
      rows: ref([] as any[]),
      loading: ref(false),
      selectedUserId: ref(),
      groupUsers: ref([] as any),
      add_users_dialog: ref(false),
      removeFromOtherGroups: ref(false),
      usersDropdownList: shallowRef([] as any),
    };
  },
});
</script>

<style scoped lang="scss">
/* DOCB-8815: fill the parent pane instead of hardcoding `calc(100vh - 450px)`
 * on the table. The fixed viewport offset didn't track the real container
 * height, leaving the table's internal scroll area detached from the pane
 * bottom. In a height-constrained parent (GroupDetails' .members-table-region,
 * flex column) this resolves to the remaining space; in unconstrained parents
 * (e.g. the deprecated groups dialog) it falls back to natural height. */
.members-table-fill {
  flex: 1;
  min-height: 0;
}

.search-input {
  width: 40%;
  min-width: 200px;
  max-width: 480px;

  @media (max-width: 600px) {
    width: 100%;
    max-width: none;
  }
}
</style>
